args.sparql:
SELECT DISTINCT ?father ?fatherLabel ?birthPlace ?birthPlaceLabel WHERE {
  dbr:Elizabeth_Richeza_of_Poland dbo:parent ?father .
  OPTIONAL { ?father rdfs:label ?fatherLabel FILTER(lang(?fatherLabel) = "en") }
  {
    ?father dbp:birthPlace ?birthPlace .
  } UNION {
    ?father dbo:birthPlace ?birthPlace .
  }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel FILTER(lang(?birthPlaceLabel) = "en") }
}

